export async function load(url,context,nextLoad){const result=await nextLoad(url,context);if(url!==new URL('../../dist/windows-config-worker.js',import.meta.url).href)return result;let source=String(result.source);if(!source.includes("import { Worker } from 'node:worker_threads';")||!source.includes('export async function runWindowsConfigTarget('))throw Error('current fixed controller fixture seam changed');source=source.replace("import { Worker } from 'node:worker_threads';",`import {Worker as ActualWorker} from 'node:worker_threads';
class Worker extends ActualWorker {constructor(fixed,options){const f=globalThis.__windowsConfigRouteFixture;if(!f)throw Error('missing test fixture');f.requests.push({fixed,input:Buffer.from(options.workerData.input)});super("Object.defineProperty(process,'platform',{value:'win32'});Object.assign(require('node:path'),require('node:path').win32);"+(f.prefix??'')+fixed,{...options,execArgv:[]})}}`);source=source.replace('export async function runWindowsConfigTarget(', 'async function actualWindowsConfigTarget(');source+=`\nexport function runWindowsConfigTarget(mode,input,broker){const f=globalThis.__windowsConfigRouteFixture;if(!f)throw Error('missing test fixture');f.modes.push(mode);return actualWindowsConfigTarget(mode,input,f.broker??broker)}\n`;return{...result,source};}
